    private ImageIcon getTreeIcon(
            TreeSpecies species
    )
    {
        if (species == null)
        {
            return null;
        }

        // Use cached icon if already loaded
        ImageIcon cachedIcon =
                treeIconCache.get(species);

        if (cachedIcon != null)
        {
            return cachedIcon;
        }

        try
        {
            String resourcePath =
                    species.getIconResourcePath();

            BufferedImage image =
                    ImageUtil.loadImageResource(
                            TreeRunnerPlugin.class,
                            resourcePath
                    );

            if (image == null)
            {


                return null;
            }

            Image scaledImage =
                    image.getScaledInstance(
                            24,
                            24,
                            Image.SCALE_SMOOTH
                    );

            ImageIcon icon =
                    new ImageIcon(
                            scaledImage
                    );

            treeIconCache.put(
                    species,
                    icon
            );

            return icon;
        }
        catch (Exception e)
        {

            return null;
        }
    }
