    // =========================================================
    // SAVED CHECKBOXES
    // =========================================================

    private void saveSelectedPatches()
    {
        StringBuilder selected =
                new StringBuilder();

        for (TreePatch patch :
                TreePatch.values())
        {
            JCheckBox checkBox =
                    patchCheckBoxes.get(
                            patch
                    );

            if (
                    checkBox != null
                            && checkBox.isSelected()
            )
            {
                if (selected.length() > 0)
                {
                    selected.append(",");
                }

                selected.append(
                        patch.name()
                );
            }
        }

        configManager.setConfiguration(
                "treerunner",
                "savedRoutePatches",
                selected.toString()
        );
    }

    private void loadSelectedPatches()
    {
        String saved =
                configManager.getConfiguration(
                        "treerunner",
                        "savedRoutePatches"
                );

        if (
                saved == null
                        || saved.isEmpty()
        )
        {
            return;
        }

        String[] patchNames =
                saved.split(",");

        for (String patchName :
                patchNames)
        {
            try
            {
                TreePatch patch =
                        TreePatch.valueOf(
                                patchName
                        );

                JCheckBox checkBox =
                        patchCheckBoxes.get(
                                patch
                        );

                if (checkBox != null)
                {
                    checkBox.setSelected(
                            true
                    );

                    JLabel status =
                            patchStatusLabels.get(
                                    patch
                            );

                    if (status != null)
                    {
                        status.setText(
                                "Selected"
                        );
                    }
                }
            }
            catch (
                    IllegalArgumentException ignored
            )
            {
                // Ignore obsolete saved patch names.
            }
        }
    }

// =========================================================
// PATCH TIMES REFRESH
// =========================================================

    public void refreshPatchTimes()
    {
        SwingUtilities.invokeLater(() ->
        {
            if (patchTimesPanel == null)
            {
                return;
            }

            /*
             * Refresh the contents of the existing
             * Patch Times card instead of replacing
             * the card itself.
             *
             * This prevents CardLayout from switching
             * back to Run Setup during a timer refresh.
             */
            JPanel updatedPanel =
                    createPatchTimesPanel();

            patchTimesPanel.removeAll();

            Component[] updatedComponents =
                    updatedPanel.getComponents();

            for (Component component :
                    updatedComponents)
            {
                patchTimesPanel.add(
                        component
                );
            }

            patchTimesPanel.revalidate();
            patchTimesPanel.repaint();
        });
    }

