            button.setBackground(
                    ColorScheme.DARKER_GRAY_COLOR
            );

            button.setBorder(
                    BorderFactory.createMatteBorder(
                            0,
                            0,
                            2,
                            0,
                            ORANGE
                    )
            );
        }
        else
        {
            button.setBackground(
                    ColorScheme.DARK_GRAY_COLOR
            );

            button.setBorder(
                    BorderFactory.createEmptyBorder(
                            0,
                            0,
                            2,
                            0
                    )
            );
        }

        return button;
    }

    private void setSelectedTab(
            JButton selected,
            JButton other
    )
    {
        selected.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        selected.setBorder(
                BorderFactory.createMatteBorder(
                        0,
                        0,
                        2,
                        0,
                        ORANGE
                )
        );

        other.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        other.setBorder(
                BorderFactory.createEmptyBorder(
                        0,
                        0,
                        2,
                        0
                )
        );
    }

    // =========================================================
    // OUTER PANEL / SCROLLBAR
    // =========================================================

    private void styleOuterPanel()
    {
        SwingUtilities.invokeLater(() ->
        {
            Container component =
                    this;

            while (component != null)
            {
                if (component
                        instanceof JScrollPane)
                {
                    JScrollPane scrollPane =
                            (JScrollPane) component;

                    scrollPane.setBorder(
                            BorderFactory
                                    .createLineBorder(
                                            Color.BLACK,
                                            1
                                    )
                    );

                    scrollPane
                            .getViewport()
                            .setBorder(null);

                    scrollPane
                            .getViewport()
                            .setBackground(
                                    ColorScheme.DARK_GRAY_COLOR
                            );

                    JScrollBar vertical =
                            scrollPane
                                    .getVerticalScrollBar();

                    styleScrollBar(
                            vertical
                    );

                    vertical.revalidate();
                    vertical.repaint();

                    scrollPane.revalidate();
                    scrollPane.repaint();

                    return;
                }

                component =
                        component.getParent();
            }
        });
    }

    private void styleScrollBar(
            JScrollBar scrollBar
    )
    {
        final Color track =
                ColorScheme.DARKER_GRAY_COLOR;

        scrollBar.setPreferredSize(
                new Dimension(
                        7,
                        0
                )
        );

        scrollBar.setMinimumSize(
                new Dimension(
                        7,
                        0
                )
        );

        scrollBar.setUnitIncrement(16);
        scrollBar.setOpaque(true);
        scrollBar.setBackground(track);
        scrollBar.setBorder(null);

        scrollBar.setUI(
                new BasicScrollBarUI()
                {
                    @Override
                    protected void configureScrollBarColors()
                    {
                        thumbColor = ORANGE;
                        thumbHighlightColor = ORANGE;
                        thumbLightShadowColor = ORANGE;
                        thumbDarkShadowColor = ORANGE;

                        trackColor = track;
                        trackHighlightColor = track;
                    }

                    @Override
                    protected JButton createDecreaseButton(
                            int orientation
                    )
                    {
                        return createZeroButton();
                    }

                    @Override
                    protected JButton createIncreaseButton(
                            int orientation
                    )
                    {
                        return createZeroButton();
                    }

                    private JButton createZeroButton()
                    {
                        JButton button =
                                new JButton();

                        Dimension zero =
                                new Dimension(
                                        0,
                                        0
                                );

                        button.setPreferredSize(
                                zero
                        );

                        button.setMinimumSize(
                                zero
                        );

                        button.setMaximumSize(
                                zero
                        );

                        return button;
                    }
                }
        );
    }

    // =========================================================
    // ORANGE CHECKBOX ICON
    // =========================================================

    private static class TreeRunnerCheckBoxIcon
            implements Icon
    {
        private static final int SIZE =
                14;

        private final boolean selected;

        private TreeRunnerCheckBoxIcon(
                boolean selected
        )
        {
            this.selected = selected;
        }

        @Override
        public void paintIcon(
                Component component,
                Graphics graphics,
                int x,
                int y
        )
        {
            Graphics2D g2 =
                    (Graphics2D)
                            graphics.create();

            if (selected)
            {
                g2.setColor(
                        ORANGE
                );

                g2.fillRect(
                        x,
                        y,
                        SIZE,
                        SIZE
                );

                g2.setColor(
                        ColorScheme
                                .DARKER_GRAY_COLOR
                );

                g2.setStroke(
                        new BasicStroke(2f)
                );

                g2.drawLine(
                        x + 3,
                        y + 7,
                        x + 6,
                        y + 10
                );

                g2.drawLine(
                        x + 6,
                        y + 10,
                        x + 11,
                        y + 4
                );
            }
            else
            {
                g2.setColor(
                        ColorScheme
                                .DARKER_GRAY_COLOR
                );

                g2.fillRect(
                        x,
                        y,
                        SIZE,
                        SIZE
                );

                g2.setColor(
                        ColorScheme
                                .LIGHT_GRAY_COLOR
                );

                g2.drawRect(
