package com.treerunner;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.Stroke;

public class TreeRunnerPatchOverlay extends Overlay
{
    private static final Stroke OUTLINE_STROKE =
            new BasicStroke(2);

    private final Client client;
    private final TreeRunManager treeRunManager;
    private final TreePatchLocator treePatchLocator;
    private final TreeRunnerConfig config;

    @Inject
    public TreeRunnerPatchOverlay(
            TreeRunnerPlugin plugin,
            Client client,
            TreeRunManager treeRunManager,
            TreePatchLocator treePatchLocator,
            TreeRunnerConfig config
    )
    {
        super(plugin);

        this.client = client;
        this.treeRunManager = treeRunManager;
        this.treePatchLocator = treePatchLocator;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.highlightCurrentPatch())
        {
            return null;
        }

        TreeRunStep currentStep =
                treeRunManager.getCurrentStep();

        if (currentStep == null)
        {
            return null;
        }

        for (TreePatch patch :
                currentStep.getPatches())
        {
            WorldArea area =
                    treePatchLocator.getPatchArea(
                            patch
                    );

            if (area != null)
            {
                renderPatchObject(
                        graphics,
                        area
                );
            }
        }

        return null;
    }

    private void renderPatchObject(
            Graphics2D graphics,
            WorldArea patchArea
    )
    {
        if (patchArea.getPlane()
                != client.getPlane())
        {
            return;
        }

        Scene scene =
                client.getScene();

        if (scene == null)
        {
            return;
        }

        Tile[][][] tiles =
                scene.getTiles();

        int plane =
                client.getPlane();

        if (plane < 0
                || plane >= tiles.length)
        {
            return;
        }

        Stroke oldStroke =
                graphics.getStroke();

        graphics.setStroke(
                OUTLINE_STROKE
        );

        for (int sceneX = 0;
             sceneX < tiles[plane].length;
             sceneX++)
        {
            for (int sceneY = 0;
                 sceneY < tiles[plane][sceneX].length;
                 sceneY++)
            {
                Tile tile =
                        tiles[plane][sceneX][sceneY];

                if (tile == null)
                {
                    continue;
                }

                WorldPoint tileLocation =
                        tile.getWorldLocation();

                if (tileLocation == null
                        || !patchArea.contains(
                        tileLocation
                ))
                {
                    continue;
                }

                GameObject[] gameObjects =
                        tile.getGameObjects();

                if (gameObjects == null)
                {
                    continue;
                }

                for (GameObject gameObject :
                        gameObjects)
                {
                    if (gameObject == null)
                    {
                        continue;
                    }

                    /*
                     * Large game objects can appear on
                     * multiple tiles.
                     *
                     * Only render the object from its
                     * minimum scene location so it isn't
                     * highlighted multiple times.
                     */
                    if (!gameObject
                            .getSceneMinLocation()
                            .equals(
                                    tile.getSceneLocation()
                            ))
                    {
                        continue;
                    }

                    WorldPoint objectLocation =
                            gameObject
                                    .getWorldLocation();

                    if (objectLocation == null
                            || !patchArea.contains(
                            objectLocation
                    ))
                    {
                        continue;
                    }

                    Shape hull =
                            gameObject
                                    .getConvexHull();

                    if (hull == null)
                    {
                        continue;
                    }

                    /*
                     * Get the colour selected in
                     * Tree Runner settings.
                     */
                    Color outlineColor =
                            config.highlightColor();

                    /*
                     * Use the same colour with transparency
                     * for the inside of the patch.
                     */
                    Color fillColor =
                            new Color(
                                    outlineColor.getRed(),
                                    outlineColor.getGreen(),
                                    outlineColor.getBlue(),
                                    50
                            );

                    /*
                     * Fill the patch object.
                     */
                    graphics.setColor(
                            fillColor
                    );

                    graphics.fill(hull);

                    /*
                     * Draw the solid outline.
                     */
                    graphics.setColor(
                            outlineColor
                    );

                    graphics.draw(hull);
                }
            }
        }

        graphics.setStroke(
                oldStroke
        );
    }
}

package com.treerunner;

import com.google.inject.Provides;
import javax.inject.Inject;
import java.awt.image.BufferedImage;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.widgets.Widget;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

@PluginDescriptor(
		name = "Tree Runner",
		description = "Helps plan and track tree farming runs",
		tags = {"farming", "tree", "trees"}
)
public class TreeRunnerPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TreeRunManager treeRunManager;

	@Inject
	private TreeRunnerOverlay overlay;

	@Inject
	private TreeRunnerPatchOverlay patchOverlay;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private TreeRunnerPanel panel;

	@Inject
	private Client client;

	@Inject
	private TravelAvailabilityManager travelAvailabilityManager;

	@Inject
	private TreePatchLocator treePatchLocator;

	@Inject
	private ItemManager itemManager;

	@Inject
	private PatchTracker patchTracker;

	private WorldPoint lastPatchClicked;
	private int lastPatchObjectId = -1;
	private TreeSpecies pendingPlantingSpecies;
	private TreePatch pendingPlantingPatch;
	private int pendingPlantingItemId = -1;
	private int pendingPlantingInitialCount = 0;
	private int pendingPlantingTicksRemaining = 0;
	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(patchOverlay);

		BufferedImage icon = ImageUtil.loadImageResource(
				TreeRunnerPlugin.class,
				"/farming_icon.png"
		);

		navigationButton = NavigationButton.builder()
				.tooltip("Tree Runner")
				.icon(icon)
				.priority(5)
				.panel(panel)
				.build();

		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(patchOverlay);

		panel.stopRefreshTimer();

		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
	}
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuAction action =
				event.getMenuAction();

		boolean plantingSapling =
				action
						== MenuAction
						.WIDGET_TARGET_ON_GAME_OBJECT;

		boolean clearingPatch =
				event.getMenuOption()
						.equalsIgnoreCase("Clear")
						|| event.getMenuOption()
						.equalsIgnoreCase("Chop down");

		if (!plantingSapling
				&& !clearingPatch)
		{
			return;
		}

		if (client.getLocalPlayer() == null)
		{
			return;
		}

		TreeSpecies plantedSpecies =
				null;

		int plantingItemId =
				-1;

		if (plantingSapling)
		{
			Widget selectedWidget =
					client.getSelectedWidget();

			if (selectedWidget != null)
			{
				plantingItemId =
						selectedWidget.getItemId();

				if (plantingItemId > 0)
				{
					String itemName =
							itemManager
									.getItemComposition(
											plantingItemId
									)
									.getName();

					plantedSpecies =
							TreeSpecies
									.fromSaplingName(
											itemName
									);


					;
				}
			}
		}

		lastPatchClicked =
				WorldPoint.fromScene(
						client,
						event.getParam0(),
						event.getParam1(),
						client.getPlane()
				);

		lastPatchObjectId =
				event.getId();

		WorldPoint playerLocation =
				client.getLocalPlayer()
						.getWorldLocation();

		TreePatch detectedPatch =
				treePatchLocator
						.findNearestPatch(
								playerLocation,
								10
						);

		if (detectedPatch == null)
		{

			return;
		}

		/*
		 * Do not record the tree yet.
		 *
		 * Store it as pending and wait until
		 * the sapling actually leaves inventory.
		 */
		if (plantingSapling
				&& plantedSpecies != null
				&& plantingItemId > 0)
		{
			pendingPlantingSpecies =
					plantedSpecies;

			pendingPlantingPatch =
					detectedPatch;

			pendingPlantingItemId =
					plantingItemId;

			pendingPlantingInitialCount =
					countInventoryItem(
							plantingItemId
					);

			pendingPlantingTicksRemaining =
					5;

		}

		if (clearingPatch) {
		}
	}
	@Subscribe
	public void onChatMessage(ChatMessage event) {
		if (event.getType() != ChatMessageType.SPAM
				&& event.getType() != ChatMessageType.GAMEMESSAGE) {
			return;
		}

		String message = event.getMessage();

		if (message == null) {
			return;
		}

		String lowerMessage = message.toLowerCase();

		if (!lowerMessage.startsWith("you plant the ")
				|| !lowerMessage.contains(" sapling in the tree patch")) {
			return;
		}

		String speciesName = lowerMessage
				.replace("you plant the ", "")
				.replace(" sapling in the tree patch.", "")
				.trim();

		TreeSpecies plantedSpecies =
				TreeSpecies.fromSaplingName(
						speciesName + " sapling"
				);

		if (plantedSpecies == null) {

			return;
		}

		if (client.getLocalPlayer() == null) {
			return;
		}

		WorldPoint playerLocation =
				client.getLocalPlayer()
						.getWorldLocation();

		TreePatch detectedPatch =
				treePatchLocator.findNearestPatch(
						playerLocation,
						5
				);

		if (detectedPatch == null) {

			;

			return;
		}

		patchTracker.recordPlanting(
				detectedPatch,
				plantedSpecies,
				java.time.Instant.now()
		);

		panel.refreshPatchTimes();

		treeRunManager.markPatchCompleted(
				detectedPatch
		);


	}
	private int countInventoryItem(
			int itemId
	)
	{
		ItemContainer inventory =
				client.getItemContainer(
						InventoryID.INVENTORY
				);

		if (inventory == null)
		{
			return 0;
		}

		int count = 0;

		for (Item item :
				inventory.getItems())
		{
			if (item != null
					&& item.getId() == itemId)
			{
				count += item.getQuantity();
			}
		}

		return count;
	}

	private void confirmPendingPlanting()
	{
		if (pendingPlantingSpecies == null
				|| pendingPlantingPatch == null)
		{
			return;
		}

		patchTracker.recordPlanting(
				pendingPlantingPatch,
				pendingPlantingSpecies,
				java.time.Instant.now()
		);

		panel.refreshPatchTimes();

		treeRunManager.markPatchCompleted(
				pendingPlantingPatch
		);

		panel.refreshCurrentRoute();

		clearPendingPlanting();
	}

	private void clearPendingPlanting()
	{
		pendingPlantingSpecies = null;
		pendingPlantingPatch = null;
		pendingPlantingItemId = -1;
		pendingPlantingInitialCount = 0;
		pendingPlantingTicksRemaining = 0;
	}
	@Subscribe
	public void onGameTick(GameTick event)
	{
		travelAvailabilityManager.refreshCarriedItems();

		if (pendingPlantingSpecies != null
				&& pendingPlantingItemId > 0)
		{
			int currentCount =
					countInventoryItem(
							pendingPlantingItemId
					);

			/*
			 * Successful planting consumes one sapling.
			 */
			if (currentCount
					< pendingPlantingInitialCount)
			{
				confirmPendingPlanting();
			}
			else
			{
				pendingPlantingTicksRemaining--;

				/*
				 * Nothing was consumed, so assume the
				 * interaction failed or was a misclick.
				 */
				if (pendingPlantingTicksRemaining <= 0)
				{
					clearPendingPlanting();
				}
			}
		}

		treeRunManager.checkPrimeRun();
	}
	@Provides
	TreeRunnerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TreeRunnerConfig.class);
	}
}

package com.treerunner;

import java.time.Duration;

public enum TreeSpecies
{
    OAK("Oak", TreeType.NORMAL, Duration.ofMinutes(160)),
    WILLOW("Willow", TreeType.NORMAL, Duration.ofHours(4)),
    MAPLE("Maple", TreeType.NORMAL, Duration.ofMinutes(320)),
    YEW("Yew", TreeType.NORMAL, Duration.ofMinutes(400)),
    MAGIC("Magic", TreeType.NORMAL, Duration.ofHours(8)),

    APPLE("Apple", TreeType.FRUIT, Duration.ofHours(16)),
    BANANA("Banana", TreeType.FRUIT, Duration.ofHours(16)),
    ORANGE("Orange", TreeType.FRUIT, Duration.ofHours(16)),
    CURRY("Curry", TreeType.FRUIT, Duration.ofHours(16)),
    PINEAPPLE("Pineapple", TreeType.FRUIT, Duration.ofHours(16)),
    PAPAYA("Papaya", TreeType.FRUIT, Duration.ofHours(16)),
    PALM("Palm", TreeType.FRUIT, Duration.ofHours(16)),
    DRAGONFRUIT("Dragonfruit", TreeType.FRUIT, Duration.ofHours(16)),

    TEAK("Teak", TreeType.HARDWOOD, Duration.ofMinutes(4480)),
    MAHOGANY("Mahogany", TreeType.HARDWOOD, Duration.ofMinutes(5120)),
    CAMPHOR("Camphor", TreeType.HARDWOOD, Duration.ofMinutes(5120)),
    IRONWOOD("Ironwood", TreeType.HARDWOOD, Duration.ofMinutes(5120)),
    ROSEWOOD("Rosewood", TreeType.HARDWOOD, Duration.ofMinutes(6400)),

    CALQUAT("Calquat", TreeType.CALQUAT, Duration.ofMinutes(1280)),
    CELASTRUS("Celastrus", TreeType.CELASTRUS, Duration.ofMinutes(800)),
    REDWOOD("Redwood", TreeType.REDWOOD, Duration.ofMinutes(6400)),
    CRYSTAL("Crystal", TreeType.CRYSTAL, Duration.ofMinutes(480));

    private final String displayName;
    private final TreeType treeType;
    private final Duration growthTime;

    TreeSpecies(
            String displayName,
            TreeType treeType,
            Duration growthTime
    )
    {
        this.displayName = displayName;
        this.treeType = treeType;
        this.growthTime = growthTime;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public TreeType getTreeType()
    {
        return treeType;
    }

    public Duration getGrowthTime()
    {
        return growthTime;
    }

    // =========================================================
    // TREE ICON
    // =========================================================

    public String getIconResourcePath()
    {
        /*
         * Fruit tree resources use names like:
         *
         * Papaya_tree(grown).png
         * Palm_tree(grown).png
         *
         * Other tree resources use names like:
         *
         * Willow_tree.png
         * Yew_tree.png
         * Teak_tree.png
         */
        if (treeType == TreeType.FRUIT)
        {
            return "/"
                    + displayName
                    + "_tree(grown).png";
        }

        return "/"
                + displayName
                + "_tree.png";
    }

    public static TreeSpecies fromSaplingName(
            String itemName
    )
    {
        if (itemName == null)
        {
            return null;
        }

        String normalized =
                itemName.toLowerCase();

        for (TreeSpecies species :
                values())
        {
            String speciesName =
                    species.getDisplayName()
                            .toLowerCase();

            if (normalized.contains(speciesName)
                    && normalized.contains("sapling"))
            {
                return species;
            }
        }

        return null;
    }
}

